// Reolink doorbell webhook (camera Settings > webhook -> http://10.0.0.208:1880/doorbell).
// The camera pushes on its own, so nothing holds a connection to it for button presses.
// Every call is logged; a VISITOR (button press) pushes Colm. The camera sends no
// "ended" message, and repeats within 15 s are logged but not pushed.
const ts = new Date().toLocaleString('en-IE', {timeZone: 'Europe/Dublin', hour12: false});
let body = msg.payload;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) {} }
const alarm = (body && body.alarm) || {};
const type = String(alarm.type || '').toUpperCase();
const ip = (msg.req && msg.req.ip) || '';
const raw = (typeof body === 'string' ? body : JSON.stringify(body || {})).slice(0, 600);
const line = function(tag){ return {payload: ts + '  [' + tag + '] from ' + ip + ' ' + raw + '\n'}; };

if (type !== 'VISITOR') return [null, line(type || 'no type')];
const now = Date.now();
if (now - (context.get('last') || 0) < 15000) return [null, line('VISITOR repeat, no push')];
context.set('last', now);
return [{title: '🔔 Doorbell', message: 'Someone pressed the doorbell',
         ndata: {tag: 'doorbell_press', ttl: 0, priority: 'high'}}, line('VISITOR push')];
